create table if not exists aria_memory.capability_gaps(gap_id uuid primary key default gen_random_uuid(),capability_id text not null,description text not null,priority integer not null default 100,status text not null default 'detected' check(status in('detected','planned','mission_created','resolved','dismissed')),evidence jsonb not null default '{}',confidence numeric(5,4) not null default .8 check(confidence between 0 and 1),mission_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(capability_id,description));
alter table aria_memory.capability_gaps enable row level security; revoke all on aria_memory.capability_gaps from anon,authenticated; grant select,insert,update,delete on aria_memory.capability_gaps to service_role;
create or replace function aria_memory.register_capability_gap(p_capability_id text,p_description text,p_priority integer default 100,p_evidence jsonb default '{}',p_confidence numeric default .8) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin insert into aria_memory.capability_gaps(capability_id,description,priority,evidence,confidence) values(trim(p_capability_id),trim(p_description),p_priority,coalesce(p_evidence,'{}'),p_confidence) on conflict(capability_id,description) do update set priority=least(aria_memory.capability_gaps.priority,excluded.priority),evidence=aria_memory.capability_gaps.evidence||excluded.evidence,confidence=greatest(aria_memory.capability_gaps.confidence,excluded.confidence),updated_at=now() returning gap_id into v_id; return v_id; end; $$;
create or replace function aria_memory.promote_capability_gap(p_gap_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare g aria_memory.capability_gaps%rowtype; r jsonb; v_mission text; begin select * into g from aria_memory.capability_gaps where gap_id=p_gap_id for update; if not found then raise exception 'capability_gap_not_found'; end if; if g.status='mission_created' and g.mission_id is not null then return jsonb_build_object('status','mission_created','gap_id',g.gap_id,'mission_id',g.mission_id); end if; v_mission:='selfdev_'||replace(lower(g.capability_id),' ','_')||'_'||substr(g.gap_id::text,1,8); r:=aria_internal.aria_mission_create(jsonb_build_object('mission_id',v_mission,'goal','Develop missing ARIA capability: '||g.capability_id||'. '||g.description,'metadata',jsonb_build_object('self_development',true,'capability_gap_id',g.gap_id,'priority',g.priority,'evidence',g.evidence),'checkpoint',jsonb_build_object('development_contract',jsonb_build_object('stages',jsonb_build_array('design','implementation','test','security','ci','deploy','evaluation'))))); update aria_memory.capability_gaps set status='mission_created',mission_id=v_mission,updated_at=now() where gap_id=g.gap_id; return jsonb_build_object('status','mission_created','gap_id',g.gap_id,'mission_id',v_mission,'mission',r); end; $$;
revoke all on function aria_memory.register_capability_gap(text,text,integer,jsonb,numeric),aria_memory.promote_capability_gap(uuid) from public,anon,authenticated; grant execute on function aria_memory.register_capability_gap(text,text,integer,jsonb,numeric),aria_memory.promote_capability_gap(uuid) to service_role;
create or replace function aria_internal.select_cognitive_model(p_capability text,p_preferred_provider text default null) returns table(model_id text,provider_id text,model_name text,score numeric,reason text) language sql security definer set search_path='' as $$ with candidates as (select m.model_id,m.provider_id,m.display_name as model_name,(case when cm.status='verified' then 100 else 0 end)+(case when m.status='available' then 50 else 0 end)+(case when m.integration_status='connected' then 25 else 0 end)+(case when m.enabled then 10 else 0 end)+(case when p.enabled then 5 else 0 end)+(case when p.status='available' then 5 when p.status='degraded' then 1 else 0 end)+(case when p_capability is not null and cm.capability_id=p_capability then 50 else 0 end)+(case when p_preferred_provider is not null and m.provider_id=p_preferred_provider then 20 else 0 end)-least(p.priority,100)::numeric as score,case when cm.status='verified' and m.status='available' and m.integration_status='connected' then 'verified_connected' else 'fallback_candidate' end as reason from aria_internal.model_registry m join aria_internal.provider_registry p on p.provider_id=m.provider_id left join aria_internal.capability_matrix cm on cm.model_id=m.model_id and cm.capability_id=p_capability where m.enabled=true and p.enabled=true and m.status in('available','degraded') and p.status in('available','degraded')) select model_id,provider_id,model_name,score,reason from candidates order by score desc,model_id limit 1; $$;
revoke all on function aria_internal.select_cognitive_model(text,text) from public,anon,authenticated; grant execute on function aria_internal.select_cognitive_model(text,text) to service_role;
